// src/pages/business/LoyaltyPage.tsx
import React, { useEffect, useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import TextBox from "../../components/common/TextBox";
import Button from "../../components/common/Button";
import api from "../../utils/api";

const PageWrapper = styled.div`
  min-height: 100vh;
  background: #f7f7fb;
`;

const Content = styled.div`
  max-width: 960px;
  margin: 32px auto;
  padding: 0 24px 48px;
`;

const HeaderRow = styled.div`
  margin-bottom: 24px;
`;

const Title = styled.h1`
  font-size: 32px;
  font-weight: 700;
  margin: 0 0 4px;
  color: #1f1f2b;
`;

const Subtitle = styled.p`
  margin: 0;
  font-size: 14px;
  color: #6b6b7a;
`;

const Card = styled.div`
  background: #ffffff;
  border-radius: 18px;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06);
  padding: 24px 28px 28px;
`;

const FormSection = styled.div`
  & + & {
    margin-top: 20px;
  }
`;

const ToggleRow = styled.label`
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  color: #2f3142;

  input {
    width: 16px;
    height: 16px;
  }
`;

const SectionLabel = styled.h2`
  font-size: 16px;
  font-weight: 600;
  margin: 16px 0 8px;
  color: #1f1f2b;
`;

const HelperText = styled.p`
  font-size: 12px;
  color: #8b8ba0;
  margin: 0 0 12px;
`;

const RewardsList = styled.div`
  display: flex;
  flex-direction: column;
  gap: 12px;
`;

const RewardRow = styled.div`
  display: flex;
  gap: 12px;
  align-items: flex-end;
`;

const RemoveRewardButton = styled.button`
  border: none;
  background: transparent;
  color: #d14b4b;
  font-size: 13px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 999px;

  &:hover {
    background: rgba(209, 75, 75, 0.08);
  }
`;

const AddRewardButton = styled.button`
  margin-top: 8px;
  border: none;
  background: transparent;
  color: #364fc7;
  font-size: 13px;
  cursor: pointer;
  padding: 4px 0;
  font-weight: 500;

  &:hover {
    text-decoration: underline;
  }
`;

const FooterRow = styled.div`
  margin-top: 24px;
  display: flex;
  justify-content: flex-end;
`;

const Message = styled.p<{ $type: "error" | "success" }>`
  font-size: 13px;
  margin-top: 12px;
  color: ${(props) => (props.$type === "error" ? "#d14b4b" : "#1f8f5f")};
`;

interface LoyaltyFormState {
  enabled: boolean;
  rewards: string[];
}

const LoyaltyPage: React.FC = () => {
  const businessId = localStorage.getItem("businessId");

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const [form, setForm] = useState<LoyaltyFormState>({
    enabled: false,
    rewards: [""],
  });

  useEffect(() => {
    const fetchLoyalty = async () => {
      try {
        setLoading(true);
        setError("");
        const res = await api.get(`/business/${businessId}/loyalty`);

        if (res.data) {
          const existingRewards =
            Array.isArray(res.data.rewards) && res.data.rewards.length > 0
              ? res.data.rewards
              : [res.data.rewardDescription || ""];

          setForm({
            enabled: !!res.data.enabled,
            rewards: existingRewards.length > 0 ? existingRewards : [""],
          });
        }
      } catch (err) {
        console.error(err);
        setError("Failed to load loyalty settings.");
      } finally {
        setLoading(false);
      }
    };

    if (businessId) {
      fetchLoyalty();
    } else {
      setLoading(false);
      setError("No businessId found. (Check auth / localStorage)");
    }
  }, [businessId]);

  const updateReward = (index: number, value: string) => {
    setForm((prev) => {
      const rewards = [...prev.rewards];
      rewards[index] = value;
      return { ...prev, rewards };
    });
    setError("");
    setSuccess("");
  };

  const addReward = () => {
    setForm((prev) => ({ ...prev, rewards: [...prev.rewards, ""] }));
    setError("");
    setSuccess("");
  };

  const removeReward = (index: number) => {
    setForm((prev) => {
      const rewards = prev.rewards.filter((_, i) => i !== index);
      return { ...prev, rewards: rewards.length > 0 ? rewards : [""] };
    });
    setError("");
    setSuccess("");
  };

  const handleToggleEnabled = (checked: boolean) => {
    setForm((prev) => ({ ...prev, enabled: checked }));
    setError("");
    setSuccess("");
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!businessId) return;

    try {
      setSaving(true);
      setError("");
      setSuccess("");

      const cleanedRewards = form.rewards
        .map((r) => r.trim())
        .filter((r) => r.length > 0);

      const payload = {
        enabled: form.enabled,
        type: "points",          // always points-based
        pointsPerBooking: 1,     // 1 point per completed booking
        rewardThreshold: 5,      // 5 points = full tile
        rewardDescription: cleanedRewards[0] || "",
        expiryMonths: 0,
        rewards: cleanedRewards,
      };

      const res = await api.put(`/business/${businessId}/loyalty`, payload);

      const updatedRewards =
        Array.isArray(res.data.rewards) && res.data.rewards.length > 0
          ? res.data.rewards
          : [res.data.rewardDescription || ""];

      setForm({
        enabled: !!res.data.enabled,
        rewards: updatedRewards.length > 0 ? updatedRewards : [""],
      });

      setSuccess("Loyalty settings saved.");
    } catch (err) {
      console.error(err);
      setError("Failed to save loyalty settings.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <PageWrapper>
      <TabBar type="business" />
      <Content>
        <HeaderRow>
          <Title>Loyalty Program</Title>
          <Subtitle>
            Configure the points-based rewards your customers see in the app.
            Each loyalty tile is unlocked after 5 points.
          </Subtitle>
        </HeaderRow>

        <Card>
          {loading ? (
            <p>Loading...</p>
          ) : (
            <form onSubmit={handleSubmit}>
              <FormSection>
                <ToggleRow>
                  <input
                    type="checkbox"
                    checked={form.enabled}
                    onChange={(e) => handleToggleEnabled(e.target.checked)}
                  />
                  <span>Enable loyalty program for this business</span>
                </ToggleRow>
                <HelperText>
                  When disabled, customers won&apos;t see any loyalty tiles for
                  your salon.
                </HelperText>
              </FormSection>

              <FormSection>
                <SectionLabel>Loyalty rewards</SectionLabel>
                <HelperText>
                  These are the rewards that show inside each loyalty tile. All
                  rewards are based on 5 points (5 visits).
                </HelperText>

                <RewardsList>
                  {form.rewards.map((reward, index) => (
                    <RewardRow key={index}>
                      <TextBox
                        label={
                          index === 0 ? "Reward name or description" : undefined
                        }
                        placeholder="e.g. Free blow-dry, 20% off next visit"
                        value={reward}
                        onChange={(
                          e: React.ChangeEvent<HTMLInputElement>
                        ) => updateReward(index, e.target.value)}
                      />
                      {form.rewards.length > 1 && (
                        <RemoveRewardButton
                          type="button"
                          onClick={() => removeReward(index)}
                        >
                          Remove
                        </RemoveRewardButton>
                      )}
                    </RewardRow>
                  ))}
                </RewardsList>

                <AddRewardButton type="button" onClick={addReward}>
                  + Add another loyalty reward
                </AddRewardButton>
              </FormSection>

              {error && <Message $type="error">{error}</Message>}
              {success && <Message $type="success">{success}</Message>}

              <FooterRow>
                <Button type="submit" disabled={saving}>
                  {saving ? "Saving..." : "Save loyalty settings"}
                </Button>
              </FooterRow>
            </form>
          )}
        </Card>
      </Content>
    </PageWrapper>
  );
};

export default LoyaltyPage;
